import Foundation

// MARK: - Program catalog (300+ ready-made programs)
//
// A browsable library of ready-made programs for everyday users,
// generated by program-library-generator/generate.py from the
// 1,635-exercise library. Every program is a real plan: real
// exercises for the right muscles, goal-appropriate rep ranges,
// and a finisher on every day.
//
// The built-in personal preset is NOT in this catalog and is not
// counted here — it lives in WorkoutData.swift. Nothing in this
// file copies it: no personal split, weights, or structure.
//
// Programs are stored as compact specs (exercise ids per day) and
// built into UserPrograms at runtime with ProgramGenerator.template,
// so sets, reps, and starting weights always follow the same
// rules as generated programs and can never drift from the library.
// Add this file to the Xcode target (it is not in project.pbxproj yet).

/// What a catalog program trains for.
enum CatalogGoal: String, Codable, CaseIterable {
    case buildMuscle, strength, lean, endurance, athletic, generalFitness

    var label: String {
        switch self {
        case .buildMuscle: return "Build Muscle"
        case .strength: return "Strength"
        case .lean: return "Get Lean"
        case .endurance: return "Endurance"
        case .athletic: return "Strength & Power"
        case .generalFitness: return "General Fitness"
        }
    }

    /// The app Goal whose set/rep rules this catalog goal uses.
    var appGoal: Goal {
        switch self {
        case .buildMuscle: return .buildMuscle
        case .strength: return .getStronger
        case .lean: return .getLean
        case .endurance: return .getLean
        case .athletic: return .getStronger
        case .generalFitness: return .buildMuscle
        }
    }
}

/// Experience level of a catalog program.
enum CatalogLevel: String, Codable, CaseIterable {
    case beginner, intermediate, advanced

    var label: String {
        switch self {
        case .beginner: return "Beginner"
        case .intermediate: return "Intermediate"
        case .advanced: return "Advanced"
        }
    }

    var experience: ExperienceLevel {
        switch self {
        case .beginner: return .new
        case .intermediate: return .some
        case .advanced: return .experienced
        }
    }
}

/// How a catalog program splits its training days.
enum CatalogSplit: String, Codable, CaseIterable {
    case fullBody, upperLower, pushPullLegs, pushPullLegsUpperLower, broSplit

    var label: String {
        switch self {
        case .fullBody: return "Full Body"
        case .upperLower: return "Upper/Lower"
        case .pushPullLegs: return "Push/Pull/Legs"
        case .pushPullLegsUpperLower: return "Push/Pull/Legs + Upper/Lower"
        case .broSplit: return "Bro Split"
        }
    }
}

/// One catalog entry: a ready-made program plus its browse metadata.
struct CatalogProgram: Identifiable, Codable, Equatable {
    var program: UserProgram
    var goal: CatalogGoal
    var level: CatalogLevel
    var daysPerWeek: Int
    var equipment: EquipmentAccess
    var durationWeeks: Int
    var split: CatalogSplit
    var focus: String
    var id: String { program.id }
}

/// The program catalog.
enum ProgramLibrary {

    /// All catalog programs.
    static let all: [CatalogProgram] = buildAll()

    static func programs(goal: CatalogGoal) -> [CatalogProgram] {
        all.filter { $0.goal == goal }
    }

    static func programs(level: CatalogLevel) -> [CatalogProgram] {
        all.filter { $0.level == level }
    }

    static func programs(daysPerWeek: Int) -> [CatalogProgram] {
        all.filter { $0.daysPerWeek == daysPerWeek }
    }

    static func programs(equipment: EquipmentAccess) -> [CatalogProgram] {
        all.filter { $0.equipment == equipment }
    }

    static func program(id: String) -> CatalogProgram? {
        all.first { $0.id == id }
    }

    // MARK: - Private

    private struct Spec {
        var id: String
        var name: String
        var goal: CatalogGoal
        var level: CatalogLevel
        var daysPerWeek: Int
        var equipment: EquipmentAccess
        var durationWeeks: Int
        var split: CatalogSplit
        var focus: String
        var days: [DaySpec]
    }

    private struct DaySpec {
        var key: String
        var title: String
        var subtitle: String
        var exerciseIds: [String]
        var finisher: [String]
    }

