    // The full catalog: the chunks concatenated, in the same
    // order as the single literal they replace.
    private static let specs: [Spec] = specsPart1 + specsPart2 + specsPart3 + specsPart4 + specsPart5 + specsPart6

    private static func buildAll() -> [CatalogProgram] {
        specs.map { buildProgram(from: $0) }
    }

    private static func buildProgram(from spec: Spec) -> CatalogProgram {
        let profile = UserProfile(
            goal: spec.goal.appGoal, experience: spec.level.experience,
            daysPerWeek: spec.daysPerWeek,
            equipmentHave: spec.equipment.equipment,
            injuredParts: [], otherLimitText: "",
            bodyweightLb: nil, bodyweightIsKg: false,
            notificationsAllowed: false, targetAreas: [])
        var days: [DayPlan] = []
        for day in spec.days {
            var templates: [ExerciseTemplate] = []
            for id in day.exerciseIds {
                guard let lib = ExerciseLibrary.byId(id) else { continue }
                var template = ProgramGenerator.template(for: lib, profile: profile)
                // Level sets: beginners do one fewer set (min 2),
                // advanced lifters one more (max 5).
                switch spec.level {
                case .beginner: template.sets = max(2, template.sets - 1)
                case .advanced: template.sets = min(5, template.sets + 1)
                case .intermediate: break
                }
                templates.append(template)
            }
            days.append(DayPlan(key: day.key, title: day.title,
                                subtitle: day.subtitle, exercises: templates,
                                finisher: day.finisher))
        }
        let program = UserProgram(id: spec.id, name: spec.name, days: days,
                                  swaps: [], isPreset: false)
        return CatalogProgram(program: program, goal: spec.goal,
                              level: spec.level, daysPerWeek: spec.daysPerWeek,
                              equipment: spec.equipment,
                              durationWeeks: spec.durationWeeks,
                              split: spec.split, focus: spec.focus)
    }
}

/// Hashable by its id, so a row can push it by state (navigationDestination).
extension CatalogProgram: Hashable {
    func hash(into hasher: inout Hasher) { hasher.combine(id) }
}
